import dev.hua.ptcglive.ai.*;
import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.effect.*;
import java.util.*;

public final class NonPokemonBatch117Test {
    static final UUID A=GeneratedRuleBatch8Test.A,B=GeneratedRuleBatch8Test.B;
    static final List<String> IDS=List.of("swsh11_en_152");
    static void check(boolean b,String why){if(!b)throw new AssertionError(why);}
    static void reject(Runnable r){GeneratedRuleBatch8Test.reject(r);}
    static UUID other(UUID p){return p.equals(A)?B:A;}
    static dev.hua.ptcglive.rules.CardInstance hand(ServerMatch m,UUID p){return DynamicPassiveModifierTest.hand(m,p,"trainer");}
    static ServerMatch aiGame(String id){var c=new GeneratedRuleBatch28Test.Config();c.trainer=NonPokemonBatch2Test.DATA.trainer(id).orElseThrow();c.attack=GeneratedRuleBatch8Test.hit(300,false);c.defenderAttack=c.attack;return GeneratedRuleBatch28Test.fixture(c);}
    static ServerMatch game(){return aiGame(IDS.getFirst());}
    static void start(ServerMatch m,UUID p){m.playTrainer(p,hand(m,p).instanceId(),null);}
    static void swap(ServerMatch m,UUID p){var q=m.effectCardPrompt(p);m.submitEffectCards(p,q.resolutionId(),q.step(),List.of(q.candidates().getFirst().instanceId()));}
    public static void main(String[] args){positions();declineAndBoundary();authority();ai();schema();System.out.println("NonPokemonBatch117Test passed: Arc Phone both players/all six positions, private top-only inspection, optional decline and all-face-up inspection, empty/one-card decks, exact no-shuffle physical swap and preserved public slots, no prize reward or hidden identity leak, stale/foreign/replayed requests, concession and four AI difficulties");}
    static void positions(){for(UUID p:List.of(A,B))for(int slot=0;slot<6;slot++)for(boolean shortDeck:List.of(false,true)){
        var m=game();if(p.equals(B))m.endTurn(A);if(shortDeck){var deck=PairedTrainerPlayTest.zone(m,p,"deck");var discard=PairedTrainerPlayTest.zone(m,p,"discard");while(deck.size()>1)discard.add(deck.removeFirst());}var deck=m.privateView(p).deck();var prizes=m.privateView(p).prizes();var source=hand(m,p);var top=deck.getLast();var chosen=prizes.get(slot);int held=m.privateView(p).hand().size();var rng=m.randomTranscript();var opponent=m.privateView(other(p));
        start(m,p);var q=m.effectCardPrompt(p);check(q.inspectedCards().equals(List.of(top))&&q.candidates().equals(List.of(top)),"Phone exposed more than top card");check(m.clientView(other(p)).effectSelection()==null&&m.clientView(null).effectSelection()==null,"Phone top leaked to opponent/spectator");swap(m,p);var choice=m.effectChoicePrompt(p);check(choice.optionsZh().size()==6&&choice.optionsZh().get(slot).equals("与第"+(slot+1)+"张暗面奖赏交换"),"Prize choice exposed names or mapped wrong slots");m.chooseEffectOption(p,choice.resolutionId(),choice.step(),slot);
        var expectedDeck=new ArrayList<>(deck);expectedDeck.set(expectedDeck.size()-1,chosen);var expectedPrizes=new ArrayList<>(prizes);expectedPrizes.set(slot,top);check(m.privateView(p).deck().equals(expectedDeck)&&m.privateView(p).prizes().equals(expectedPrizes),"Phone shuffled or swapped wrong physical cards");check(m.privateView(p).hand().size()==held-1&&m.privateView(p).discard().contains(source)&&m.privateView(other(p)).equals(opponent)&&m.randomTranscript().equals(rng),"Phone changed unrelated zones/RNG");check(!m.hasPendingEffectChoice()&&m.effectCardReveal()==null&&!m.hasPendingLuckyBonus(p)&&m.phase()==MatchPhase.TURN&&m.currentPlayer().equals(p),"Phone revealed selected prize, awarded prize or stalled");check(m.clientView(other(p)).players().stream().filter(v->v.id().equals(p)).findFirst().orElseThrow().faceUpPrizes().isEmpty(),"Phone made swapped cards face-up");reject(()->m.chooseEffectOption(p,choice.resolutionId(),choice.step(),0));
    }}
    static void declineAndBoundary(){for(UUID p:List.of(A,B))for(boolean allUp:List.of(false,true)){
        var m=game();if(p.equals(B))m.endTurn(A);var deck=m.privateView(p).deck();var prizes=m.privateView(p).prizes();if(allUp)prizes.forEach(c->NonPokemonBatch116Test.faces(m,p).add(c.instanceId()));var faces=m.clientView(other(p)).players().stream().filter(v->v.id().equals(p)).findFirst().orElseThrow().faceUpPrizes();var rng=m.randomTranscript();check(m.canPlayTrainer(p,hand(m,p).instanceId(),null),"All-face-up prizes prevented top inspection");start(m,p);var q=m.effectCardPrompt(p);check(q.inspectedCards().equals(List.of(deck.getLast()))&&(!allUp||q.candidates().isEmpty()&&q.maximum()==0),"All-face-up Phone offered exchange or skipped inspection");m.submitEffectCards(p,q.resolutionId(),q.step(),List.of());check(m.privateView(p).deck().equals(deck)&&m.privateView(p).prizes().equals(prizes)&&m.randomTranscript().equals(rng)&&!m.hasPendingEffectChoice(),"Decline changed cards/RNG or stalled");check(m.clientView(other(p)).players().stream().filter(v->v.id().equals(p)).findFirst().orElseThrow().faceUpPrizes().equals(faces),"Phone changed face-up state");
    }var m=game();var deck=PairedTrainerPlayTest.zone(m,A,"deck");PairedTrainerPlayTest.zone(m,A,"discard").addAll(deck);deck.clear();check(!m.canPlayTrainer(A,hand(m,A).instanceId(),null),"Phone playable with empty deck");
        var n=game();var prizes=n.privateView(A).prizes();NonPokemonBatch116Test.faces(n,A).add(prizes.get(1).instanceId());NonPokemonBatch116Test.faces(n,A).add(prizes.get(4).instanceId());var top=n.privateView(A).deck().getLast();start(n,A);swap(n,A);var q=n.effectChoicePrompt(A);check(q.optionsZh().equals(List.of("与第1张暗面奖赏交换","与第3张暗面奖赏交换","与第4张暗面奖赏交换","与第6张暗面奖赏交换")),"Face-up slots included or reindexed");n.chooseEffectOption(A,q.resolutionId(),q.step(),3);check(n.privateView(A).prizes().get(5).equals(top)&&n.privateView(A).prizes().get(1).equals(prizes.get(1))&&n.privateView(A).prizes().get(4).equals(prizes.get(4)),"Sparse prize slot mapping corrupted face-up cards");
    }
    static void authority(){var m=game();start(m,A);var first=m.effectCardPrompt(A);var before=m.clientView(A);var rng=m.randomTranscript();reject(()->m.effectCardPrompt(B));reject(()->m.submitEffectCards(B,first.resolutionId(),first.step(),List.of(first.candidates().getFirst().instanceId())));reject(()->m.submitEffectCards(A,first.resolutionId(),first.step(),List.of(m.privateView(A).deck().getFirst().instanceId())));check(before.equals(m.clientView(A))&&rng.equals(m.randomTranscript()),"Invalid inspection changed state");swap(m,A);var q=m.effectChoicePrompt(A);before=m.clientView(A);reject(()->m.chooseEffectOption(B,q.resolutionId(),q.step(),0));reject(()->m.chooseEffectOption(A,UUID.randomUUID(),q.step(),0));reject(()->m.chooseEffectOption(A,q.resolutionId(),first.step(),0));reject(()->m.chooseEffectOption(A,q.resolutionId(),q.step(),6));check(before.equals(m.clientView(A))&&rng.equals(m.randomTranscript()),"Invalid exchange choice mutated state");
        var deck=PairedTrainerPlayTest.zone(m,A,"deck");Collections.swap(deck,0,1);before=m.clientView(A);reject(()->m.chooseEffectOption(A,q.resolutionId(),q.step(),0));check(before.equals(m.clientView(A))&&rng.equals(m.randomTranscript()),"Stale deck snapshot partly exchanged cards");Collections.swap(deck,0,1);m.chooseEffectOption(A,q.resolutionId(),q.step(),0);
        var n=game();var source=hand(n,A);start(n,A);swap(n,A);n.concede(B);check(n.phase()==MatchPhase.FINISHED&&!n.hasPendingEffectChoice()&&n.privateView(A).discard().contains(source),"Concede stranded Phone or lost played Item");
    }
    static void ai(){for(var level:AiDifficulty.values()){var m=game();start(m,A);var s=MatchSession.multiplayer(m,A,B);AiCardOperationTest.settle(s,level);AiCardOperationTest.finish(s,level);check(m.phase()==MatchPhase.FINISHED,"Phone AI stalled: "+level);}}
    static void schema(){for(var e:List.of(new EffectDefinition(TopPrizeSwap.INSPECT,EffectTarget.SELF,Map.of(),List.of(),List.of()),new EffectDefinition(TopPrizeSwap.INSPECT,EffectTarget.DECK,Map.of("position","0"),List.of(),List.of()),new EffectDefinition(TopPrizeSwap.RESOLVE,EffectTarget.SELF,Map.of("position","-1"),List.of(),List.of()),new EffectDefinition(TopPrizeSwap.RESOLVE,EffectTarget.SELF,Map.of("position","60"),List.of(),List.of())))reject(()->EffectSchemaValidator.validate(e));}
}
